1658:.action-notice-empty { min-height: 0; padding: 0; }
1659:.action-notice-text { margin: 0; font-size: var(--type-body); display: flex; gap: 2px 12px; flex-wrap: wrap; align-items: baseline; }
1660:.action-notice-label { color: var(--text-primary); font-weight: var(--weight-strong); }
1661:.action-notice-status { color: var(--text-secondary); }
1662:.action-notice-expired { color: var(--warning); }
1663:.action-notice-undo { display: flex; gap: 2px; align-items: center; }
1665:.action-notice-undo button,
1669:.action-notice-undo { margin-left: -8px; }
1670:.action-notice-undo kbd,

